from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle
from pypdf import PdfReader, PdfWriter
ROOT=Path(__file__).resolve().parents[2];B=ROOT/'docs/audit-remediation';build=ROOT/'docs/user-manual/build';build.mkdir(exist_ok=True)
original=build/'original-audit.pdf';original.write_bytes(subprocess.check_output(['git','show','e3daf0e:output/pdf/EasyGas-Website-Audit.pdf'],cwd=ROOT))
