story=[p('EasyGas website audit remediation','Title'),p('20 November 2026    Client demo release'),p('The audited help and verification defects have been fixed and deployed. Nine explicitly approved demo-only notices are published. Missing financial values and single-owner authority now have clearer explanations. Commercial production remains NO-GO.'),p('Current release','Heading2'),p('Stable site: https://easygas-client-demo.vercel.app'),p('Application source b10829aa447a7ae5bd430a73f9644e2feca854a6. Ready deployment dpl_Ewd4EFdg7QEGbaAgqxAzBZ4MBiVN was promoted to the stable client-demo domain.'),p('Approved scope','Heading2'),p('The user approved the exact nine demo notices and a fresh two-hour synthetic QA renewal. The notices exclude real sales. The meter and four labelled staff qualifications expire at 18:31:17 UTC on 19 November 2026: 19:31 Lagos and 04:31 Brisbane on 20 November. No automatic extension or real safety certification is implied.'),p('How to read this report','Heading2'),p('These first three pages update the original 13-page read-only audit that follows. Original observations, screenshots and dates are historical evidence. Current results below supersede their defect status; the original record is retained. All seven findings remain tracked, including blocked and partial items.'),PageBreak(),p('Current finding status','Heading1')]
rows=[['ID','Current result','Outstanding scope'],['WEB-A01','Verified for client demo','Commercial policy review remains required.'],['WEB-A02','Verified fixed','Public contact route works; customer messages remain protected.'],['WEB-A03','Verified fixed','Correct resend guidance; live email delivery is a separate gate.'],['WEB-A04','Verified within approved window','Expires automatically; genuine physical evidence still required.'],['WEB-A05','Blocked','Production gates and nine high or critical incidents remain.'],['WEB-A06','Partial','One owner supported; confirm actual staff maker and reviewer roles.'],['WEB-A07','Verified explanation','Cost reconciliation and native telemetry acceptance remain separate.']]
t=Table([[p(c,'CellText')for c in r]for r in rows],colWidths=[65,155,284],repeatRows=1)
t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8edf0')),('GRID',(0,0),(-1,-1),.5,colors.HexColor('#d9d9d9')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),11),('BOTTOMPADDING',(0,0),(-1,-1),11)]))
story+=[t,Spacer(1,14),p('Five of seven findings are verified within the approved demo remediation scope. The nine-requirement phase matrix also tracks deployment and documentation. No requirement is excluded from its denominator.'),p('Sole-owner operation','Heading2'),p('Customer Policies uses the existing owner authority for eligible business notices. This does not add owners or waive independent financial, access, payment or qualified safety review. Existing QA identities demonstrate checks; they do not establish real company staffing.'),PageBreak(),p('Verification and remaining gates','Heading1'),p('Executed verification','Heading2'),p('The web build and focused recovery, approval, policy and meter tests passed. Browser checks covered all nine public notices, the actual technician support click, verification account link, financial explanations and readiness guidance. Phone checks covered verification and policy reading.'),p('Hosted product API checks preserved the 13 existing orders, ledger, inventory, gas, customer wallet, current loyalty policy and all 32 original approval requests. Sixteen expected role-access responses passed, including ten denials. No new commercial transaction was created.'),p('Safety evidence','Heading2'),p('The temporary qualification records retain independent verifiers. Driver recalibration was denied and a past calibration expiry was rejected. Isolated regression tests also check expiry, stale meter evidence and role restrictions. This pass does not claim another complete physical or hosted gas journey.'),p('Release limits','Heading2'),p('Production NO-GO, actual-import hold and retain-all remain. Real commercial policies, staff responsibilities, incident resolution, providers, monitoring, backup and restore, privacy fulfilment, native distribution, device GPS and physical safety acceptance are still governed separately.'),p('Evidence and manual','Heading2'),p('docs/audit-remediation/evidence contains the exact-source manifest, Ready deployment identity, publication hashes, expiry record, hosted preservation and browser captures. docs/traceability/audit-remediation-rtm.json retains all seven finding IDs and both release requirements. The illustrated user manual is Edition 2.'),p('Original audit follows','Heading2'),p('The next page begins the original read-only audit with its original page numbering. Statements that no renewal or publication occurred describe that earlier audit, before the separately approved remediation recorded above.')]
def foot(c,d):c.setFont('Helvetica',8);c.drawString(54,30,'EasyGas remediation update | 20 November 2026');c.drawRightString(558,30,str(d.page))
add=build/'audit-addendum.pdf';SimpleDocTemplate(str(add),pagesize=letter,leftMargin=54,rightMargin=54,topMargin=50,bottomMargin=48).build(story,onFirstPage=foot,onLaterPages=foot)
assert len(PdfReader(add).pages)==3
w=PdfWriter();w.append(add);w.append(original);w.write(ROOT/'output/pdf/EasyGas-Website-Audit.pdf')
